({
  _ensureInitialized() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {};
    }
    if (!this.data.metrics || typeof this.data.metrics !== 'object') {
      this.data.metrics = {};
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', "this.data must be an object");
    this.invariant(this.data.metrics && typeof this.data.metrics === 'object', "this.data.metrics must be an object");
    for (const [name, samples] of Object.entries(this.data.metrics)) {
      this.invariant(typeof name === 'string' && name.length > 0, "Metric key must be a non-empty string");
      this.invariant(Array.isArray(samples), "Metric samples must be stored as an array");
      for (const sample of samples) {
        this.invariant(
          sample &&
          typeof sample === 'object' &&
          typeof sample.value === 'number' &&
          Number.isFinite(sample.value),
          "Each metric sample must have a finite numerical value"
        );
      }
    }
  },

  recordMetric(msg) {
    this.ensure(msg && typeof msg.payload === 'object' && msg.payload !== null, "Payload must be an object");
    const { name, value, timestamp } = msg.payload;

    this.ensure(typeof name === 'string' && name.trim().length > 0, "Metric name must be a non-empty string");
    this.ensure(typeof value === 'number' && Number.isFinite(value), "Metric value must be a finite number");

    const ts = timestamp !== undefined ? timestamp : Date.now();
    this.ensure(
      typeof ts === 'number' || typeof ts === 'string' || ts instanceof Date,
      "Timestamp must be a valid number, date string, or Date instance"
    );

    this._ensureInitialized();

    const normalizedTs = typeof ts === 'number' ? ts : new Date(ts).getTime() || Date.now();
    const metricName = name.trim();

    if (!this.data.metrics[metricName]) {
      this.data.metrics[metricName] = [];
    }

    const sample = {
      value,
      timestamp: normalizedTs
    };

    this.data.metrics[metricName].push(sample);

    this._checkInvariants();
    this.changed("metricRecorded", { name: metricName, sample });

    this.ensure(
      this.data.metrics[metricName] && this.data.metrics[metricName].length > 0,
      "Metric sample must be recorded in data"
    );

    return sample;
  },

  getStats(msg) {
    this.ensure(msg && typeof msg.payload === 'object' && msg.payload !== null, "Payload must be an object");
    const { name } = msg.payload;
    this.ensure(typeof name === 'string' && name.trim().length > 0, "Metric name must be a non-empty string");

    this._ensureInitialized();
    const metricName = name.trim();
    const samples = this.data.metrics[metricName] || [];

    let stats;
    if (samples.length === 0) {
      stats = { min: 0, max: 0, avg: 0, count: 0 };
    } else {
      let min = Infinity;
      let max = -Infinity;
      let sum = 0;

      for (let i = 0; i < samples.length; i++) {
        const val = samples[i].value;
        if (val < min) min = val;
        if (val > max) max = val;
        sum += val;
      }

      stats = {
        min,
        max,
        avg: sum / samples.length,
        count: samples.length
      };
    }

    this.ensure(
      stats &&
      typeof stats.min === 'number' &&
      typeof stats.max === 'number' &&
      typeof stats.avg === 'number' &&
      typeof stats.count === 'number',
      "getStats must return an object with min, max, avg, and count numbers"
    );

    return stats;
  },

  resetMetrics(msg) {
    this.ensure(msg && typeof msg.payload === 'object' && msg.payload !== null, "Payload must be an object");
    const { name } = msg.payload;
    this.ensure(name === undefined || typeof name === 'string', "Metric name, if provided, must be a string");

    this._ensureInitialized();

    const targetName = name && name.trim().length > 0 ? name.trim() : null;

    if (targetName) {
      delete this.data.metrics[targetName];
    } else {
      this.data.metrics = {};
    }

    this._checkInvariants();
    this.changed("metricsReset", { name: targetName || "all" });

    const isReset = targetName ? !this.data.metrics[targetName] : Object.keys(this.data.metrics).length === 0;
    this.ensure(isReset, "Specified metrics must be cleared from state");

    return { reset: targetName || "all" };
  }
})
